dtsPropsFor.AiCard:
/** The optional link band across the top. Omit it and the card opens straight on the
	 *  headline. `progress` draws the scan glyph beside the title; `destination` is spoken
	 *  after the visible text as ", open <destination>". */
	header?: { to: string; title: string; meta?: string; destination?: string; progress?: boolean };
	/** The bold line the eye lands on. */
	headline?: string;
	/** The sentence under the headline. */
	body?: React.ReactNode;
	/** The action row at the foot. Pass `<Button variant="invert">`, `<ButtonLink
	 *  className="button-link-invert">` and `<AiCardMark />` - the card is dark, so a
	 *  default-styled button disappears into it. */
	children?: React.ReactNode;
	[key: string]: unknown;

dtsPropsFor.AiCardMark:
/** Width and height in pixels. Defaults to 44 (the stylesheet's own size); the New order
	 *  rail uses 34. */
	size?: number;

dtsPropsFor.Async:
/** Exactly what `useApi` returns. `data === undefined` is the wait, a non-null `error`
	 *  is the failure, and anything else is loaded. `loading` only marks a background
	 *  refetch - the last good render stays on screen through it. */
	state: { data?: unknown; error?: { status?: number; message?: string } | null; loading?: boolean };
	/** A function, not markup. It is called with `state.data` and only once that data is
	 *  there, so it may read the record without guarding for undefined. */
	children: (data: any) => React.ReactNode;
	/** What is being waited for, in the reader's words: "Loading your orders". Printed on
	 *  the plain waiting card and spoken on the waiting region. Defaults to "Loading". */
	label?: string;
	/** A region shaped like the answer, shown instead of the plain waiting card - built
	 *  from SkeletonCard, SkeletonRows and SkeletonKpiRow. Leave it out where there is no
	 *  good approximation and the Waiting card shows instead. */
	skeleton?: React.ReactNode;

dtsPropsFor.Button:
/** Space-separated variant words, each becoming a `button-<word>` class:
	 *  primary | outline | ghost | caps | compact | block | pill | invert | link | link-invert. */
	variant?: string;
	/** An in-app route. Renders a react-router link. */
	to?: string;
	/** A URL outside the app. Renders a plain anchor. */
	href?: string;
	/** An Icon name placed before the label. */
	icon?: string;
	/** An Icon name placed after the label. */
	iconAfter?: string;
	/** The label. */
	children?: React.ReactNode;
	className?: string;
	onClick?: (event: React.MouseEvent) => void;
	type?: "button" | "submit" | "reset";
	disabled?: boolean;
	[key: string]: unknown;

dtsPropsFor.ButtonLink:
/** An in-app route. Renders a react-router link; without it, a real `<button>`.
	 *  Both forms are underlined and otherwise identical. */
	to?: string;
	/** The words, written in capitals: SEE ALL, CLEAR ALL, ADD AN ORDER. */
	children?: React.ReactNode;
	/** `button-link-invert` for a dark surface such as AiCard. */
	className?: string;
	onClick?: (event: React.MouseEvent) => void;
	[key: string]: unknown;

dtsPropsFor.Card:
/** Extra class words on the section, written in full (not `card-` prefixed):
	 *  `card-tray` for the "cards you can add" tray, `card-steps` for a Stepper card. Most
	 *  cards pass nothing. */
	variant?: string;
	/** Normally `CardHeader`, `CardDivider`, then one or more `CardBody`. */
	children?: React.ReactNode;
	className?: string;
	/** Spread onto the <section>. Give every card an `aria-label` naming it. */
	[key: string]: unknown;

dtsPropsFor.CardBody:
/** Extra class words, written in full: `card-body-tight` (a list opening under the
	 *  hairline), `card-body-page` (even padding), `card-body-centered` (children centred),
	 *  `card-body-filters`, `card-body-fill` (the body takes the card's leftover height),
	 *  `entry-list` (a list of EntryRows). Combine them with a space. Never override
	 *  padding-top yourself. */
	variant?: string;
	children?: React.ReactNode;
	className?: string;
	[key: string]: unknown;

dtsPropsFor.CardHeader:
/** Usually the heading text. It is rendered as-is, so a node works too -- SkeletonCard
	 *  passes a shimmer block. A node with only a percentage width measures 0 wide here,
	 *  because the label span is a flex item sized to its own content. */
	title?: React.ReactNode;
	/** An in-app route. The whole band becomes a link and grows a right chevron. */
	to?: string;
	/** Overrides the accessible name. With `to`, it defaults to "<title>, open <to>"; give a
	 *  spoken destination instead, e.g. "Orders, open Orders". */
	label?: string;
	/** Makes the whole band a disclosure button with a chevron that points down when closed
	 *  and up when open. Mutually exclusive with `to`. */
	onToggle?: (event: React.MouseEvent) => void;
	/** Whether the panel `onToggle` controls is open. Sets aria-expanded and turns the chevron. */
	open?: boolean;
	/** The `id` of the element `onToggle` opens - a string for aria-controls, not markup. */
	controls?: string;
	/** A control for the right-hand slot, e.g. `<Button variant="pill" icon="plus">ADD</Button>`.
	 *  Keep it shorter than the band: the band sets its own height. */
	children?: React.ReactNode;
	className?: string;

dtsPropsFor.CategoryPreview:
/** The glyph's name. A key of `ICONS` draws on its own; a Tabler name needs `iconPath`
	 *  beside it. */
	icon?: string;
	/** The SVG path the record stored when the icon was chosen. It wins over `icon`, and it is
	 *  why a chosen glyph draws without loading the icon catalogue. */
	iconPath?: string;
	/** The tile's fill, as a hex string. The glyph's own ink is picked from it, so a pale fill
	 *  still shows its glyph. */
	colour?: string;
	/** The category's name. Empty draws "Your category", so the row keeps its shape while the
	 *  name is still being typed. */
	name?: string;

dtsPropsFor.CategoryRow:
/** The category record. `colour` and `icon` draw the tile, `name` the title, `spend` the
	 *  figure (formatted as whole kroner), and `share` the default meta line. `iconPath` is
	 *  a custom glyph path where the record carries one instead of a named icon. */
	category?: {
		id?: string;
		name: string;
		colour: string;
		icon: string;
		iconPath?: string | null;
		/** Percent of expenses, e.g. 38.4 — written by the row as "38,4% of expenses". */
		share?: number;
		/** Rendered in the account's currency, rounded to whole units. */
		spend: number;
	};
	/** Replaces the "38,4% of expenses" line the row writes for itself — e.g. what the spend
	 *  is against a budget. Say what stretch of time `spend` covers if it is not all time. */
	meta?: string;
	/** An in-app route. With it the whole row is a link and draws a chevron. */
	to?: string;

dtsPropsFor.CheckRow:
/** Required: the help text's id is derived from it (`<id>-help`), and so is the name's
	 *  (`<id>-label`). */
	id?: string;
	/** Controlled. */
	checked?: boolean;
	/** Gets the new checked state. */
	onChange?: (checked: boolean) => void;
	/** The bold name on the first line. This alone is the control's accessible name. */
	label?: string;
	/** The muted sentence under the name. Say what turning it off changes. */
	help?: string;

dtsPropsFor.Chip:
/** The chip's text. Kept on one line; it is cut with an ellipsis before the chip's
	 *  own edges give way. */
	children?: React.ReactNode;
	/** Takes the value away. With it the chip is a real `<button>` carrying a cross; without
	 *  it, a plain `<span>`. Never draw a cross the chip cannot honour. */
	onRemove?: (event: React.MouseEvent) => void;
	/** The button form's accessible name, e.g. "Remove filter Bilka". Pair it with `onRemove`;
	 *  ignored without one. */
	label?: string;
	/** An Icon name drawn after the label, before the cross. */
	icon?: string;
	className?: string;
	[key: string]: unknown;

dtsPropsFor.ColourPicker:
/** The chosen colour, as a hex string (`#14AC72`). A `var(--token)` reference is read off
	 *  the stylesheet, but records store the hex. A value outside `colours` rings no swatch and
	 *  fills the last box instead. */
	value?: string;
	/** Gets the chosen colour as a hex string, from a swatch or from the platform picker. */
	onChange?: (colour: string) => void;
	/** The swatches on offer. Defaults to `CATEGORY_COLOURS`; pass `VENDOR_COLOURS` for a
	 *  vendor, whose tile carries two white letters and needs the darker end. Both are exported
	 *  beside this component. Eight is the row the layout is drawn for. */
	colours?: Array<{ id: string; label: string }>;
	/** The accessible name of the whole row, e.g. "Category colour". */
	label?: string;

dtsPropsFor.Combobox:
/** The current text, or the selected option's label. */
	value?: string;
	/** The user typed. */
	onChange?: (text: string) => void;
	/** The user chose a row. */
	onSelect?: (option: { id: string; label: string }) => void;
	/** Sections of the open list. */
	groups?: Array<{ heading?: string; options: Array<{ id: string; label: string }> }>;
	/** Label for the create row, e.g. "CREATE VENDOR". Shown only once something is typed
	 *  that does not already match an option. */
	action?: string;
	placeholder?: string;
	label?: string;
	id?: string;
	required?: boolean;
	/** Error state. Pair with the surrounding Field's `error`. */
	invalid?: boolean;
	describedBy?: string;
	/** An Icon name shown inside the field, before the text. */
	leadingIcon?: string;
	/** Selected values rendered inside the shell rather than above it, so a field with
	 *  values still lines up with the field beside it. */
	chips?: React.ReactNode;
	/** Content pinned to the right of the input. */
	trail?: React.ReactNode;
	/** Chosen from, never typed into (sort orders, currencies). Removes the caret and the
	 *  mobile keyboard; click, arrow keys and Enter are unchanged. */
	pickOnly?: boolean;
	children?: React.ReactNode;
	className?: string;

dtsPropsFor.ConfirmDialog:
/** The question, ending in a question mark: "Delete this order?". Also the dialog's
	 *  accessible name. */
	title?: string;
	/** One sentence naming what is at stake, so the reader can tell they picked the right
	 *  record. `useDelete` appends "This cannot be undone." to it. */
	detail?: string;
	/** The verb on the destructive button, in capitals: "DELETE", "RELOAD". */
	confirmLabel?: string;
	/** The safe answer. Defaults to "CANCEL". */
	cancelLabel?: string;
	/** Runs the action. The caller unmounts the dialog; it does not close itself. */
	onConfirm?: () => void;
	/** Backdrop click and Escape both call this, as well as the cancel button. */
	onCancel?: () => void;

dtsPropsFor.DashboardCards:
/** The catalogue of every card that exists. `desc` is shown in the "cards you can add"
	 *  tray while editing. */
	all?: Array<{ key: string; name: string; desc: string }>;
	/** The keys this account has on its dashboard, in its own order. Every key must exist in
	 *  `all` - the component looks each one up to name it. */
	initial?: string[];
	/** Draws the inside of one card. The component supplies the <section class="card"> around
	 *  it, so return a `CardHeader` / `CardDivider` / `CardBody` group, not another Card. */
	render?: (key: string) => React.ReactNode;

dtsPropsFor.DateInput:
/** The control's id, and what the Field's `htmlFor` points at. Generated when left out. */
	id?: string;
	/** ISO `YYYY-MM-DD`, or `''` for an empty field. Never a formatted Danish date. */
	value?: string;
	/** Gets the new ISO date string, not the event. Half-typed dates arrive as `''`. */
	onChange?: (value: string) => void;
	/** Draws the red edge on the shell and sets aria-invalid. */
	invalid?: boolean;
	/** The Field's `errorId`. Only read while `invalid` is set. */
	describedBy?: string;
	/** A short note pinned beside the calendar glyph, rendered as a FieldUnit, e.g. `today`. */
	trail?: React.ReactNode;
	/** The accessible name of the input, e.g. "Order date". Set it even when a Field already
	 *  labels the row, so the name says which date. */
	label?: string;
	[key: string]: unknown;

dtsPropsFor.DeleteCard:
/** The record in words, lower case: "vendor", "category", "wish". It is uppercased into
	 *  the header and the button label. */
	what?: string;
	/** One or two sentences on what removing it does, and what stops it. */
	children?: React.ReactNode;
	/** The object `useDelete({ what, detail, onDelete })` returns. The card draws `del.button`
	 *  and `del.dialog`; the hook owns the confirmation and reads the account's
	 *  "ask before deleting" setting. */
	del?: { button: React.ReactNode; dialog: React.ReactNode; confirming?: boolean; iconButton?: React.ReactNode };

dtsPropsFor.DocumentPreview:
/** The file's own kind, as the server files it from the bytes: `image` or `pdf`. These are
	 *  the only two the stylesheet draws a glyph for — any other word renders an empty box.
	 *  Defaults to `image`. */
	kind?: 'image' | 'pdf';
	/** A thumbnail or a display image. Left out, or failing to load, the box falls back to the
	 *  glyph for `kind`. PDFs have no thumbnail, so they always fall back. */
	src?: string;
	/** `scan-source-open` for the 520px tall opened view, `scan-reading-preview` for the
	 *  120x150 thumbnail beside the reading message. */
	className?: string;
	style?: React.CSSProperties;
	[key: string]: unknown;

dtsPropsFor.Donut:
/** The arcs, in draw order clockwise from twelve o'clock. `share` is a percentage and
	 *  `colour` a CSS colour - the category's own, so the ring and the rows beside it agree.
	 *  Omitted or empty, the ring draws no arcs at all: a flat track with the centre figure
	 *  still in it. */
	segments?: { share: number; colour: string }[];
	/** The figure in the hole, already formatted (`"12.474 kr."`). It shrinks itself to
	 *  whatever the circle can hold, so a long amount needs no shortening by the caller. */
	value?: string;
	/** The small caption under the figure - what stretch of time the figure covers. */
	label?: string;
	/** The whole ring's accessible name. Recharts' own SVG stays hidden, so this is the only
	 *  thing a screen reader gets: state the figure and what it is split by. */
	ariaLabel?: string;

dtsPropsFor.DonutBox:
/** The ring. One child - whatever names its segments goes under the box, not inside it. */
	children?: React.ReactNode;
	className?: string;

dtsPropsFor.DropZone:
/** Gets the dropped or chosen files as an array. Never fired with an empty one. */
	onFiles?: (files: File[]) => void;
	/** Whether more than one file can be chosen at a time. Default `true`. */
	multiple?: boolean;
	/** What the picker offers, from `fileKinds.js`: `RECEIPT_FILES`, `PHOTO_FILES`,
	 *  `EXPORT_FILES`. Shaped `{description, accept}` - `accept` maps a MIME type to its
	 *  extensions. Where the browser has showOpenFilePicker this is the only filter offered. */
	kind?: { description: string; accept: Record<string, string[]> };
	/** An `accept` attribute written out by hand. Only for a picker with no `kind`. */
	accept?: string;
	/** The accessible name of the file input behind the zone, e.g. "Add attachments". */
	label?: string;
	/** The sentence inside the box. Say what it takes and how many, e.g. "Drop receipts here -
	 *  as many as you like - or choose them." */
	hint?: string;
	/** The text action under the sentence, written in capitals. Default `CHOOSE FILES`. */
	action?: string;
	/** The Icon name on the tile above the sentence. Default `upload`; the attachments card
	 *  uses `photo`. */
	icon?: string;

dtsPropsFor.EmptyState:
/** Icon name for the tile above the text. Defaults to `search`. Pass `null` to draw no
	 *  tile - almost never right, since every other empty state in the app has one. */
	icon?: string | null;
	/** A `<p>` saying what is absent, then at most one action - a `ButtonLink` for a text
	 *  action, `<Button variant="block">` for a full-width one. Leave the action out when
	 *  there is nothing useful to press. */
	children?: React.ReactNode;
	className?: string;
	[key: string]: unknown;

dtsPropsFor.EntityMark:
/** Draws the small star over the tile's corner. A favourite is turned on and off from
	 *  the record's own edit page — nothing here is a control. */
	favourite?: boolean;
	/** The record's own tile at its own size: an `entry-avatar` span for a vendor, a
	 *  `category-icon` span for a category. The mark overlaps its corner rather than
	 *  growing it, so favourite and plain rows keep one left column. */
	children?: React.ReactNode;

dtsPropsFor.EntityRow:
/** The record's own tile, passed in whole: a vendor's initials avatar or a category's
	 *  coloured glyph, usually inside an `EntityMark` so a favourite carries its star. */
	mark?: React.ReactNode;
	/** The record's name — the row's first line, and the link when the row goes somewhere. */
	name?: string;
	/** The quiet second line: order count, share, budget, a matched alias. */
	meta?: string;
	/** The figure on the right, already formatted. */
	amount?: React.ReactNode;
	/** A smaller second figure under `amount`, e.g. "saved 1.965 kr.". */
	sub?: string;
	/** An in-app route — the record's own edit page. Without it, and without `open`, the row
	 *  is inert: no link, no chevron. */
	editTo?: string;
	/** A second control riding on top of the row, e.g. an edit IconButton. Only meaningful
	 *  beside `open` or `editTo`, since one link cannot hold another. */
	action?: React.ReactNode;
	/** Sends the row itself out of the app, in a new tab. The row draws no chevron then —
	 *  it is leaving. `label` is what the link announces. */
	open?: { href: string; label: string } | null;

dtsPropsFor.EntryRow:
/** The record's own tile: the colour it is filled with and the initials drawn on it.
	 *  A vendor row passes the vendor record itself. The ink is picked from the fill. */
	avatar?: { initials: string; colour: string };
	/** An Icon name on the neutral grey tile, for a row that stands for something with no
	 *  colour of its own. Use instead of `avatar`, never with it. */
	glyph?: string;
	/** The row's first line — the record's name. */
	name?: string;
	/** The quiet second line: a date, an order count, a note. */
	meta?: string;
	/** The figure on the right, already formatted, e.g. "742,45 kr.". */
	amount?: React.ReactNode;
	/** A smaller second figure under `amount`, e.g. "saved 38,50 kr.". Draw it on every row
	 *  of a list or none, so the column keeps one shape. */
	sub?: string;
	/** An in-app route. With it the whole row is a link and draws a chevron; without it the
	 *  row is a plain block and claims nothing about being actionable. */
	to?: string;
	/** Extra content between the figure and the chevron. */
	children?: React.ReactNode;
	[key: string]: unknown;

dtsPropsFor.FavouriteTile:
/** The record's own tile: a vendor's initials avatar or a category's coloured glyph. */
	mark?: React.ReactNode;
	/** The record's name. */
	name?: string;
	/** An in-app route — the record's own filtered orders. The whole tile is this link. */
	to?: string;
	/** What the tile announces, since the tile is one link over four pieces of text, e.g.
	 *  "Bilka, open their orders". */
	linkLabel?: string;
	/** The quiet line under the name: an order count, or a share of expenses. */
	meta?: string;
	/** The figure, already formatted. */
	amount?: React.ReactNode;
	/** The smaller line under the figure, e.g. "saved 1.965 kr.". */
	saved?: React.ReactNode;

dtsPropsFor.FavouriteTileGrid:
/** The `FavouriteTile`s. The grid decides the columns — three across a wide panel, two
	 *  at tablet width, one per row on a phone — so a caller never sets them. */
	children?: React.ReactNode;

dtsPropsFor.Field:
/** The label above the control. */
	label?: string;
	/** Appends a muted "(optional)" to the label. Every field is required unless this says
	 *  otherwise; there is no "required" marker. */
	optional?: boolean;
	/** The rejection message, drawn under the control in red. Set it only after a submit. */
	error?: string;
	/** The id given to the error span. The control's `describedBy` must be the same string,
	 *  by convention `<control id> + "-error"`. */
	errorId?: string;
	/** Muted help text under the control (and under the error, when both are shown). */
	help?: string;
	/** The field wraps a group of controls (a segmented control, a colour picker) rather than
	 *  one control, so it renders a <div> instead of a <label>. */
	group?: boolean;
	/** The id of the control this label points at. Required whenever anything clickable sits
	 *  before the control inside the field, such as chips. Ignored when `group` is set. */
	htmlFor?: string;
	/** The control, normally a FieldShell, a Combobox, a DateInput, a TextArea or a Segmented. */
	children?: React.ReactNode;
	className?: string;
	[key: string]: unknown;

dtsPropsFor.FieldPair:
/** How the pair behaves as the window narrows:
	 *  `field-pair-keep` stays two columns on a phone (short values such as two dates) |
	 *  `field-pair-stack-early` drops to one column sooner than the default.
	 *  Left out, the pair is two equal columns that stack on a phone. */
	variant?: "field-pair-keep" | "field-pair-stack-early";
	/** Exactly two Fields. */
	children?: React.ReactNode;

dtsPropsFor.FieldShell:
/** Extra class on the shell:
	 *  `field-shell-area` (taller, for a textarea) | `field-shell-date` |
	 *  `field-shell-chips` (wraps chips onto more lines) |
	 *  `field-shell-no-chevron` (with `field-shell-chips`, when no list opens). */
	variant?: string;
	/** The control and anything riding inside the border with it: an input, an Icon, a
	 *  FieldUnit, Chips. */
	children?: React.ReactNode;
	className?: string;
	/** The element to render. `div` by default; `label` makes the whole shell clickable,
	 *  which is what the file picker uses. */
	as?: "div" | "label" | "span";
	[key: string]: unknown;

dtsPropsFor.FilterChips:
/** One entry per filter that is actually on, derived from the query string rather than
	 *  held here. `key` identifies it for removal, `label` is what the reader sees. Any
	 *  other field rides along and comes back in `onRemove` — the pages carry a `clear`
	 *  object saying which filter this chip turns off. With an empty array the component
	 *  renders nothing at all. */
	chips?: Array<{ key: string; label: string; [field: string]: unknown }>;
	/** One chip's remove button was pressed. Receives the whole chip. */
	onRemove?: (chip: { key: string; label: string; [field: string]: unknown }) => void;
	/** CLEAR ALL was pressed. Clears the filters, and keeps the sort — a sort is not a
	 *  filter. */
	onClearAll?: (...args: unknown[]) => void;
	/** Where focus lands when the last chip goes, or after CLEAR ALL. The list's own search
	 *  field, the same ref `ListToolbar` gets. */
	focusRef?: React.RefObject<HTMLElement>;

dtsPropsFor.FilterSection:
/** The controls the section groups, usually opening with a `<span className="panel-heading">`
	 *  naming them. Fields stack with the section's own 14px gap. */
	children?: React.ReactNode;
	/** The panel's id, for the `aria-controls` of the button that opens it. */
	id?: string;
	/** Spread onto the div - `hidden` closes the panel without taking it out of the DOM. */
	[key: string]: unknown;

dtsPropsFor.FilterSectionBody:
/** The optional fields, stacked with the same gap the section around them uses. */
	children?: React.ReactNode;
	/** The body's id, so the control that shows and hides it can name it in `aria-controls`. */
	id?: string;
	/** Closes it. The fields stay in the DOM with their values and take no height. */
	hidden?: boolean;

dtsPropsFor.Form:
/** Default `true`: the form fills its column. `false` caps it at 640px, for a narrow
	 *  form standing on its own such as sign-in. */
	wide?: boolean;
	/** Fields, FieldPairs, FilterSections and a closing FormActions. */
	children?: React.ReactNode;
	[key: string]: unknown;

dtsPropsFor.FormActions:
/** Pushes the two children to opposite ends: the leave action left, the save right. Use it
	 *  for the footer of a whole form. Without it the buttons sit together at the left, in
	 *  reading order, which is what a card's own actions do. */
	split?: boolean;
	/** The buttons, and anything riding with them: a `field-help form-actions-note` span for a
	 *  muted note, a `push-end` span for a control that belongs at the far end. */
	children?: React.ReactNode;

dtsPropsFor.FormPage:
/** The card's headline, and its accessible name unless `label` says otherwise. */
	title?: string;
	/** One sentence under the headline saying what the form is for. */
	lead?: string;
	/** Overrides the card's aria-label. Defaults to `title`. */
	label?: string;
	/** Draws the step banner above the card. `done` puts a check on a step behind you, `on`
	 *  marks the one you are on. Leave it out for a form that is not a wizard. */
	steps?: Array<{ label: string; icon: string; done?: boolean; on?: boolean }>;
	/** A verdict about the whole form, drawn between the lead and the first field - normally a
	 *  `Note`. Never a rejection of one field: that belongs under the field. */
	notice?: React.ReactNode;
	/** The column beside the form: the live summary card, and on an edit form a `DeleteCard`.
	 *  Pass a fragment for more than one card. */
	rail?: React.ReactNode;
	/** The left button of the footer, described rather than built - the page draws it as a
	 *  ghost button. `label` defaults to "CANCEL". */
	cancel?: { to?: string; onClick?: () => void; label?: string; icon?: string };
	/** The right button of the footer, drawn as `variant="caps"`. Write the label in capitals
	 *  and swap it for "SAVING..." while the request is in flight. */
	submit?: { label: string; onClick: () => void; disabled?: boolean };
